head.script:
scwin.doInit = function() {
    common.onloadBizCom(bcm, ysm, prc);
    scvar.popupCount = 0;
    scwin.setComCode();
    scwin.doSubmission("SEARCH_CODE");
    ipbCtrtMgmtNo.focus();
};
scwin.doValidate = function(id, options) {
    switch (id) {
        case "SEARCH_CODE":
        case "SEARCH_SALES_PERSON":
            return Promise.resolve(true);
            break;
            break;
        case "SEARCH":
            return common.validateDetail("grpSchBox");
            break;
    }
};
scwin.doSubmission = function(id, options) {
    options = options || {};
    var promise = scwin.doValidate(id, options);
    promise = promise.then(function(res) {
        if (!res) return false;
        switch (id) {
            case "SEARCH_CODE":
                var ref = [{
                    id: "dmSearchParam",
                    key: "dmSearchParam"
                }];
                var tgt = [{
                    id: "dlSelSvcCvrg",
                    key: "dlSelSvcCvrg"
                }];
                var promise = common.execute("searchInitMainCode", "/UPRC0040/searchInitCode.do", ref, tgt, null, btnSearch);
                break;
            case "SEARCH_SALES_PERSON":
                var ref = [{
                    id: "dmSearchSales",
                    key: "dmSearchParam"
                }];
                var tgt = [{
                    id: "dlOutSalesPerson",
                    key: "cntrCustSrepCd"
                }];
                var promise = common.execute("searchCntrCustSrepCodeList", "/PRCCOMMONCODE/searchCntrCustSrepCodeList.do", ref, tgt, null, btnSearch);
                promise = promise.then(function(res) {
                    if (res) {
                        ipbCtrtSlesPnCd.setValue(dlOutSalesPerson.getCellData(0, "code"));
                        ipbCtrtSlesPnNm.setValue(dlOutSalesPerson.getCellData(0, "value"));
                    }
                });
                break;
            case "SEARCH":
                var ref = [{
                    id: "dmSearchParam",
                    key: "dmSearchParam"
                }];
                var tgt = [{
                    id: "dlOut",
                    key: "dlOut"
                }];
                var promise = common.execute("searchServiceContractList", "/UPRC0040/searchServiceContractList.do", ref, tgt, null, btnSearch);
                break;
        } //switch      
    });
};
