scwin.openPopup0020 = function(popupName, data) {
    var options = {
        openAction: "existWindow"
    };
    var params = {
        "svcCvrgCd": data.svcCvrgCd,
        "ctrtNo": data.ctrtNo,
        "ctrtMgmtNo": data.ctrtMgmtNo,
        "amdtSeq": data.amdtSeq
    };
    var title, url;
    if (popupName == "OPEN CONTRACT") {
        title = popupName;
        url = "/ui/container/ysm/prc/servicecontract/management/UIPRC0020.xml";
        uiID = "UIPRC0020";
    } else if (popupName == "AMENDMENT HISTORY") {
        title = popupName;
        url = "/ui/container/ysm/prc/servicecontract/management/UIPRC0020.xml";
        uiID = "UIPRC0020-1";
    }
    common.createWindow(title, url, uiID, options, params);
    /*
        arrList.forEach(function(item, index) {

            uiID = "UIPRC0020";         
            common.createWindow(popupNm,getTxtUrl,uiID);
        });
        */
    /*
        var options = {
                "width"     : "1800"
              , "height"    : "900"
              , "popupName" : "Service Contract"
              , "title"     : "Service Contract"
              , "dataObj"   : { }
            };
            var rowJSON = gvOut.getCheckedJSON( "chk" );
            options.dataObj.arrList  = gvOut.getCheckedJSON( "chk" );
            common.openPopup("UIPRC0020", options);
*/
};
scwin.openPopupHistory = function() {
    var options = {
        "width": "1300",
        "height": "700",
        "popupName": "Service Contract History",
        "title": "Service Contract History",
        "dataObj": {}
    };
    var rowJSON = gvOut.getCheckedJSON("chk");
    options.dataObj.arrList = [dlOut.getRowJSON(gvOut.getFocusedRowIndex())];
    common.openPopup("UIPRC0060", options);
};
scwin.openPopupSalesPerson = function() {
    var dataObj = {
        type: "json",
        data: {
            data: dmSearchParam.getJSON(),
            callbackFn: ""
        },
        name: "authObj"
    };
    var options = {
        id: "SalesPersonPop",
        popupName: "Sales Person Inqquiry",
        autoSearch: "Y",
        multiYn: "N",
        modal: true,
        width: 1000,
        height: 550,
        "dataObj": dmSearchParam.getJSON()
    };
    var promise = common.openPopup("/ui/container/ysm/prc/code/inquiry/UIPRC9900.xml", options);
    promise = promise.then(function(res) {
        var result = res.PARAM_DATA;
        if (result == "") {
            return;
        }
        if (!common.isEmpty(result.value)) {
            ipbCtrtSlesPnCd.setValue(result.code);
            ipbCtrtSlesPnNm.setValue(result.value);
            udcCtrtOfceCd.setValue(result.refCd);
        }
    });
    return promise;
};
scwin.setComCode = function() {
    var arrJson = [{
        code: "C04412",
        compID: "sbCtrtCustTpCd",
    }, {
        code: "C05852",
        compID: "sbCtrtAcntTierGrpCd",
    }, {
        code: "C05854",
        compID: "sbCtrtAcntGrpCd",
    }];
    var promise1 = common.setComCode(arrJson);
}
scwin.sbSvcCvrgCd_onchange = function() {
    ipbSvcCvrgNm.setValue(dlSelSvcCvrg.getMatchedColumnData("svcCvrgCd", this.getValue(), "svcCvrgNm", true));
};
scwin.udcCtrtCustOfceCd_oneditkeyup = function(info) {
    if (info.keyCode == 13) {
