};
scwin.testPopup = function() {
    var options = {
        "width": "1300",
        "height": "700",
        "popupName": "Service Contract History",
        "title": "Service Contract History",
        "dataObj": {}
    };
    var arrList = gvOut.getCheckedJSON("chk");
    var promise = Promise.resolve(true);
    for (var j = 0, len = arrList.length; j < len; j++) {
        (function(i) {
            var rowJSON = arrList[i];
            promise = promise.then(function(res) {
                options.dataObj.arrList = [rowJSON];
                return common.openPopup("UIPRC0060", options);
            });
        })(j);
    };
};
scwin.testPopup2 = function() {
    var options = {
        "width": "1300",
        "height": "700",
        "popupName": "Service Contract History",
        "title": "Service Contract History",
        "closeCallbackFnNm": "scwin.closeCallback",
        "dataObj": {}
    };
    var arrList = gvOut.getCheckedJSON("chk");
    var rowJSON = arrList[scvar.popupCount];
    options.dataObj.arrList = [rowJSON];
    scvar.popupCount++;
    return common.openPopup("UIPRC0060", options);
};
scwin.closeCallback = function() {
    scwin.testPopup2();
};
scwin.submission1_submitdone = function(e) {
    console.log("scwin.submission1_submitdone", e);
};
scwin.checkVal = function() {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.getErrorLog = function() {
    var temp = WebSquare.logger.getErrorLog();
    return temp;
    // return temp.indexOf("error문구");
    // return temp.indexOf("error");
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "console.log(mf_dlOut.setJSON([]))");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.getErrorLog() == ''", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
